/**
 * @name Path traversal via URL parsing
 * @description URL parsing that could lead to path traversal vulnerabilities
 * @kind path-problem
 * @problem.severity high
 * @id py/path-traversal-url
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for file operations that use URL path components
    sink = any(FileSystemAccess fa).getAPathArgument()
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from URL input to file operation $@.", source.getNode(), "user input"

/**
 * @name Inefficient regular expressions
 * @description Inefficient regular expressions can lead to ReDoS (Regular Expression Denial of Service)
 * @kind path-problem
 * @problem.severity warning
 * @id py/redos
 * @tags security
 *        external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module ReDoSConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("re").getMember(["compile", "search", "match", "fullmatch", "findall", "finditer", "split", "sub", "subn"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module ReDoSFlow = TaintTracking::Global<ReDoSConfig>;
import ReDoSFlow::PathGraph

from ReDoSFlow::PathNode source, ReDoSFlow::PathNode sink
where ReDoSFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input flows into regex pattern, potentially causing ReDoS from $@.", source.getNode(), "user input"

/**
 * @name URL scheme injection
 * @description Dangerous URL schemes could lead to file access, code execution, or other attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/url-scheme-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module UrlSchemeConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for URL parsing/processing functions that handle schemes
    exists(API::CallNode call |
      call = API::moduleImport("mdurl").getMember(["parse", "decode", "encode", "format"]).getACall() and
      sink = call.getArg(0)
    ) or
    // Also check for urllib.parse usage
    exists(API::CallNode call |
      call = API::moduleImport("urllib.parse").getMember(["urlparse", "urlsplit", "parse_qs", "parse_qsl"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module UrlSchemeFlow = TaintTracking::Global<UrlSchemeConfig>;
import UrlSchemeFlow::PathGraph

from UrlSchemeFlow::PathNode source, UrlSchemeFlow::PathNode sink
where UrlSchemeFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User input flows into URL parsing function, potentially allowing dangerous scheme injection from $@.", source.getNode(), "user input"
